@import 'tailwindcss';
@import 'tw-animate-css';

@custom-variant dark (&:is(.dark *));

:root {
  /* Warm parchment base — Bible reader palette */
  --background: oklch(0.975 0.008 80);       /* warm off-white / parchment */
  --foreground: oklch(0.22 0.018 50);        /* dark warm brown */
  --card: oklch(0.99 0.006 80);
  --card-foreground: oklch(0.22 0.018 50);
  --popover: oklch(0.99 0.006 80);
  --popover-foreground: oklch(0.22 0.018 50);
  --primary: oklch(0.42 0.07 35);            /* warm chestnut / brick */
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.93 0.014 80);         /* warm light tan */
  --secondary-foreground: oklch(0.3 0.02 50);
  --muted: oklch(0.94 0.01 80);
  --muted-foreground: oklch(0.5 0.02 60);
  --accent: oklch(0.78 0.09 65);             /* warm amber accent */
  --accent-foreground: oklch(0.18 0.02 50);
  --destructive: oklch(0.577 0.245 27.325);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(0.875 0.016 75);
  --input: oklch(0.92 0.012 78);
  --ring: oklch(0.65 0.06 55);

  /* Bible-specific tokens */
  --verse-highlight: oklch(0.91 0.09 85);    /* warm amber highlight */
  --verse-highlight-border: oklch(0.78 0.10 70);
  --note-stripe: oklch(0.42 0.07 35);        /* matches primary */
  --toolbar-bg: oklch(0.22 0.018 50);        /* dark toolbar */
  --toolbar-fg: oklch(0.96 0.006 80);

  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --radius: 0.5rem;
  --sidebar: oklch(0.96 0.01 78);
  --sidebar-foreground: oklch(0.22 0.018 50);
  --sidebar-primary: oklch(0.42 0.07 35);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.93 0.014 80);
  --sidebar-accent-foreground: oklch(0.3 0.02 50);
  --sidebar-border: oklch(0.875 0.016 75);
  --sidebar-ring: oklch(0.65 0.06 55);
}

.dark {
  --background: oklch(0.145 0 0);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.145 0 0);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.145 0 0);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.985 0 0);
  --primary-foreground: oklch(0.205 0 0);
  --secondary: oklch(0.269 0 0);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  --accent: oklch(0.269 0 0);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.396 0.141 25.723);
  --destructive-foreground: oklch(0.637 0.237 25.331);
  --border: oklch(0.269 0 0);
  --input: oklch(0.269 0 0);
  --ring: oklch(0.439 0 0);
  --chart-1: oklch(0.488 0.243 264.376);
  --chart-2: oklch(0.696 0.17 162.48);
  --chart-3: oklch(0.769 0.188 70.08);
  --chart-4: oklch(0.627 0.265 303.9);
  --chart-5: oklch(0.645 0.246 16.439);
  --sidebar: oklch(0.205 0 0);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.488 0.243 264.376);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.269 0 0);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(0.269 0 0);
  --sidebar-ring: oklch(0.439 0 0);
}

@theme inline {
  --font-sans: 'Lora', 'Georgia', serif;
  --font-serif: 'Lora', 'Georgia', serif;
  --font-mono: 'Geist Mono', 'Geist Mono Fallback';
  --color-verse-highlight: var(--verse-highlight);
  --color-verse-highlight-border: var(--verse-highlight-border);
  --color-note-stripe: var(--note-stripe);
  --color-toolbar-bg: var(--toolbar-bg);
  --color-toolbar-fg: var(--toolbar-fg);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

import type { Metadata } from 'next'
import { Lora, Geist_Mono } from 'next/font/google'
import { Analytics } from '@vercel/analytics/next'
import './globals.css'

const _lora = Lora({ subsets: ["latin"], variable: "--font-lora" });
const _geistMono = Geist_Mono({ subsets: ["latin"] });

export const metadata: Metadata = {
  title: 'Scripture Reader',
  description: 'A focused Bible reading experience with highlights and notes.',
  generator: 'v0.app',
  icons: {
    icon: [
      {
        url: '/icon-light-32x32.png',
        media: '(prefers-color-scheme: light)',
      },
      {
        url: '/icon-dark-32x32.png',
        media: '(prefers-color-scheme: dark)',
      },
      {
        url: '/icon.svg',
        type: 'image/svg+xml',
      },
    ],
    apple: '/apple-icon.png',
  },
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en">
      <body className="font-sans antialiased">
        {children}
        <Analytics />
      </body>
    </html>
  )
}

"use client";

/**
 * SelectionToolbar
 *
 * A compact floating toolbar that appears near a text selection.
 * Position it with `style={{ top, left }}` from a parent that
 * reads `window.getSelection()` coordinates.
 *
 * Integration hint:
 *   const rect = selection.getRangeAt(0).getBoundingClientRect();
 *   setToolbar({ top: rect.top + scrollY - 48, left: rect.left + rect.width / 2 });
 */

import { Highlighter, StickyNote, X } from "lucide-react";
import { cn } from "@/lib/utils";

interface SelectionToolbarProps {
  /** Absolute pixel position relative to the scroll container / document */
  position: { top: number; left: number };
  onHighlight: () => void;
  onAddNote: () => void;
  onCancel: () => void;
  className?: string;
}

export function SelectionToolbar({
  position,
  onHighlight,
  onAddNote,
  onCancel,
  className,
}: SelectionToolbarProps) {
  return (
    /**
     * Outer wrapper: absolutely positioned, centred on the midpoint of the
     * selection via `translate-x-[-50%]`.  `z-50` keeps it above verse text.
     *
     * Tailwind classes to copy if you inline this instead:
     *   "absolute z-50 -translate-x-1/2 flex items-center gap-px
     *    rounded-lg shadow-lg overflow-hidden border border-toolbar-bg/20
     *    bg-[var(--toolbar-bg)] text-[var(--toolbar-fg)]"
     */
    <div
      role="toolbar"
      aria-label="Selection actions"
      className={cn(
        "absolute z-50 -translate-x-1/2",
        "flex items-center gap-px rounded-lg overflow-hidden",
        "shadow-[0_4px_20px_rgba(0,0,0,0.35)]",
        "bg-toolbar-bg text-toolbar-fg",
        "border border-white/10",
        className
      )}
      style={{ top: position.top, left: position.left }}
    >
      {/* Pointer / caret pointing downward — pure CSS triangle */}
      <span
        aria-hidden="true"
        className={cn(
          "absolute -bottom-[6px] left-1/2 -translate-x-1/2",
          "w-0 h-0",
          "border-l-[6px] border-l-transparent",
          "border-r-[6px] border-r-transparent",
          "border-t-[6px] border-t-toolbar-bg"
        )}
      />

      <ToolbarButton
        icon={<Highlighter size={14} strokeWidth={2} />}
        label="Highlight selection"
        onClick={onHighlight}
        colorClass="hover:bg-amber-600"
      />

      <div className="w-px h-5 bg-white/15 shrink-0" aria-hidden="true" />

      <ToolbarButton
        icon={<StickyNote size={14} strokeWidth={2} />}
        label="Add note to selection"
        onClick={onAddNote}
        colorClass="hover:bg-primary/80"
      />

      <div className="w-px h-5 bg-white/15 shrink-0" aria-hidden="true" />

      <ToolbarButton
        icon={<X size={14} strokeWidth={2.5} />}
        label="Cancel selection"
        onClick={onCancel}
        colorClass="hover:bg-white/10"
      />
    </div>
  );
}

/* ─── Internal sub-component ─────────────────────────────────────────── */

interface ToolbarButtonProps {
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
  colorClass?: string;
}

function ToolbarButton({ icon, label, onClick, colorClass }: ToolbarButtonProps) {
  return (
    <button
      type="button"
      aria-label={label}
      title={label}
      onClick={onClick}
      className={cn(
        "flex items-center gap-1.5 px-3 py-2",
        "text-xs font-medium leading-none whitespace-nowrap",
        "transition-colors duration-100 cursor-pointer",
        "focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-white/40",
        colorClass ?? "hover:bg-white/10"
      )}
    >
      {icon}
      <span>{label.split(" ")[0]}</span>
    </button>
  );
}

"use client";

/**
 * VerseBlock
 *
 * Renders a single Bible verse with:
 *  - verse number superscript
 *  - optional highlight state (amber wash)
 *  - optional note indicator dot
 *  - selected state (blue-ish ring, used during multi-verse drag)
 *
 * Usage:
 *   <VerseBlock
 *     number={3}
 *     text="For God so loved the world..."
 *     highlighted
 *     hasNote
 *     onMouseUp={handleMouseUp}
 *   />
 *
 * Tailwind class summary for quick reference:
 *   Highlighted:  bg-verse-highlight border-l-2 border-verse-highlight-border
 *   Selected:     ring-1 ring-primary/40 bg-primary/5
 *   Note dot:     w-1.5 h-1.5 rounded-full bg-note-stripe
 */

import { cn } from "@/lib/utils";

export interface VerseBlockProps {
  number: number;
  text: string;
  highlighted?: boolean;
  selected?: boolean;
  hasNote?: boolean;
  "data-verse"?: number;
  onMouseUp?: (e: React.MouseEvent<HTMLParagraphElement>) => void;
  onMouseDown?: (e: React.MouseEvent<HTMLParagraphElement>) => void;
  className?: string;
}

export function VerseBlock({
  number,
  text,
  highlighted = false,
  selected = false,
  hasNote = false,
  onMouseUp,
  onMouseDown,
  className,
  ...rest
}: VerseBlockProps) {
  return (
    <p
      data-verse={number}
      onMouseUp={onMouseUp}
      onMouseDown={onMouseDown}
      className={cn(
        /* Base */
        "relative group pl-6 pr-2 py-1.5 rounded-sm",
        "font-serif text-base leading-relaxed text-foreground",
        "transition-colors duration-150 cursor-text select-text",
        /* Highlighted state */
        highlighted && [
          "bg-verse-highlight",
          "border-l-[3px] border-verse-highlight-border",
          "pl-5", // compensate for border
        ],
        /* Selected (active drag) state */
        selected && !highlighted && [
          "bg-primary/8 ring-1 ring-inset ring-primary/30",
        ],
        className
      )}
      {...rest}
    >
      {/* Verse number */}
      <sup
        className={cn(
          "mr-1.5 text-[0.65rem] font-semibold select-none",
          "font-sans tabular-nums",
          highlighted ? "text-note-stripe" : "text-muted-foreground"
        )}
        aria-label={`Verse ${number}`}
      >
        {number}
      </sup>

      {text}

      {/* Note indicator dot */}
      {hasNote && (
        <span
          aria-label="Has note"
          title="Note attached"
          className={cn(
            "inline-block ml-1.5 mb-0.5 align-middle",
            "w-1.5 h-1.5 rounded-full shrink-0",
            "bg-note-stripe opacity-80"
          )}
        />
      )}
    </p>
  );
}

"use client";

/**
 * NoteCard
 *
 * Displays a single reader note in the right-side panel.
 * Shows:
 *  - verse reference badge (e.g. "v. 3–4")
 *  - selected-text preview (truncated, italic)
 *  - note body text
 *  - Edit / Delete action buttons
 *
 * Usage:
 *   <NoteCard
 *     id="note-1"
 *     verseRef="v. 3–4"
 *     selectedText="For God so loved the world..."
 *     noteText="This is the key verse of the gospel."
 *     onEdit={() => openEditor("note-1")}
 *     onDelete={() => deleteNote("note-1")}
 *   />
 */

import { Pencil, Trash2 } from "lucide-react";
import { cn } from "@/lib/utils";

export interface NoteCardProps {
  id: string;
  verseRef: string;
  selectedText: string;
  noteText: string;
  onEdit: () => void;
  onDelete: () => void;
  className?: string;
}

export function NoteCard({
  id,
  verseRef,
  selectedText,
  noteText,
  onEdit,
  onDelete,
  className,
}: NoteCardProps) {
  return (
    <article
      aria-label={`Note for ${verseRef}`}
      className={cn(
        "group relative flex flex-col gap-2",
        "rounded-md border border-border bg-card p-3",
        "transition-shadow duration-150 hover:shadow-sm",
        className
      )}
    >
      {/* Left accent stripe — matches the verse highlight border */}
      <span
        aria-hidden="true"
        className="absolute left-0 top-3 bottom-3 w-[3px] rounded-full bg-note-stripe"
      />

      {/* Header row: verse badge + actions */}
      <div className="flex items-center justify-between gap-2 pl-3">
        <span
          className={cn(
            "inline-flex items-center px-1.5 py-0.5 rounded text-[0.65rem]",
            "font-sans font-semibold tracking-wide uppercase",
            "bg-secondary text-secondary-foreground"
          )}
        >
          {verseRef}
        </span>

        {/* Actions — visible on hover / focus */}
        <div
          className={cn(
            "flex items-center gap-0.5",
            "opacity-0 group-hover:opacity-100 group-focus-within:opacity-100",
            "transition-opacity duration-150"
          )}
          role="group"
          aria-label="Note actions"
        >
          <NoteIconButton
            icon={<Pencil size={12} strokeWidth={2} />}
            label={`Edit note for ${verseRef}`}
            onClick={onEdit}
            className="hover:text-primary"
          />
          <NoteIconButton
            icon={<Trash2 size={12} strokeWidth={2} />}
            label={`Delete note for ${verseRef}`}
            onClick={onDelete}
            className="hover:text-destructive"
          />
        </div>
      </div>

      {/* Selected text preview */}
      <blockquote
        className={cn(
          "pl-3 ml-px border-l-2 border-verse-highlight-border",
          "text-xs italic text-muted-foreground leading-relaxed",
          "line-clamp-2"
        )}
      >
        &ldquo;{selectedText}&rdquo;
      </blockquote>

      {/* Note body */}
      <p className="pl-3 text-sm leading-relaxed text-foreground line-clamp-3">
        {noteText}
      </p>
    </article>
  );
}

/* ─── Internal icon button ─────────────────────────────────────────────── */

interface NoteIconButtonProps {
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
  className?: string;
}

function NoteIconButton({ icon, label, onClick, className }: NoteIconButtonProps) {
  return (
    <button
      type="button"
      aria-label={label}
      title={label}
      onClick={onClick}
      className={cn(
        "p-1.5 rounded text-muted-foreground",
        "transition-colors duration-100 cursor-pointer",
        "focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
        className
      )}
    >
      {icon}
    </button>
  );
}

"use client";

/**
 * NotesPanel
 *
 * Right-side panel listing all reader notes for the current chapter.
 *
 * Responsive behaviour:
 *  - md+: fixed-width right column (w-72 xl:w-80), scrollable independently
 *  - <md:  stacks below the main reading column (full width)
 *
 * Toggle visibility on mobile via the `open` prop + a button in the parent.
 *
 * Tailwind class summary:
 *   Panel wrapper: "w-full md:w-72 xl:w-80 shrink-0"
 *   Sticky header: "sticky top-0 z-10 bg-sidebar border-b border-border"
 *   Scroll area:   "overflow-y-auto max-h-[calc(100dvh-8rem)]"  (md+)
 */

import { BookOpen, Plus } from "lucide-react";
import { cn } from "@/lib/utils";
import { NoteCard, type NoteCardProps } from "./note-card";

export interface Note extends Omit<NoteCardProps, "onEdit" | "onDelete"> {}

interface NotesPanelProps {
  chapterRef: string; // e.g. "John 3"
  notes: Note[];
  /** Mobile: whether panel is visible (stacked below reader) */
  open?: boolean;
  onAddNote?: () => void;
  onEditNote: (id: string) => void;
  onDeleteNote: (id: string) => void;
  className?: string;
}

export function NotesPanel({
  chapterRef,
  notes,
  open = true,
  onAddNote,
  onEditNote,
  onDeleteNote,
  className,
}: NotesPanelProps) {
  return (
    <aside
      aria-label={`Notes for ${chapterRef}`}
      className={cn(
        /* Layout */
        "flex flex-col",
        "w-full md:w-72 xl:w-80 shrink-0",
        /* Mobile: hidden when closed */
        !open && "hidden md:flex",
        /* Visual */
        "bg-sidebar border-t border-border md:border-t-0 md:border-l",
        "md:min-h-[calc(100dvh-4rem)]",
        className
      )}
    >
      {/* ── Panel header ───────────────────────────────────────────── */}
      <header
        className={cn(
          "sticky top-0 z-10",
          "flex items-center justify-between gap-2",
          "px-4 py-3",
          "bg-sidebar border-b border-border",
          "shrink-0"
        )}
      >
        <div className="flex items-center gap-2 min-w-0">
          <BookOpen
            size={14}
            strokeWidth={2}
            className="text-primary shrink-0"
            aria-hidden="true"
          />
          <h2 className="text-sm font-semibold font-sans text-foreground truncate">
            Notes
            <span className="ml-1.5 text-muted-foreground font-normal">
              — {chapterRef}
            </span>
          </h2>
        </div>

        {onAddNote && (
          <button
            type="button"
            aria-label="Add new note"
            title="Add new note"
            onClick={onAddNote}
            className={cn(
              "flex items-center gap-1 px-2 py-1 rounded",
              "text-xs font-medium text-primary-foreground bg-primary",
              "hover:bg-primary/85 transition-colors duration-100 cursor-pointer",
              "focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring shrink-0"
            )}
          >
            <Plus size={12} strokeWidth={2.5} aria-hidden="true" />
            Add
          </button>
        )}
      </header>

      {/* ── Notes list / empty state ────────────────────────────────── */}
      <div
        className={cn(
          "flex-1 overflow-y-auto",
          "md:max-h-[calc(100dvh-8rem)]",
          "p-3 flex flex-col gap-2.5"
        )}
      >
        {notes.length === 0 ? (
          <NotesPanelEmpty />
        ) : (
          notes.map((note) => (
            <NoteCard
              key={note.id}
              {...note}
              onEdit={() => onEditNote(note.id)}
              onDelete={() => onDeleteNote(note.id)}
            />
          ))
        )}
      </div>
    </aside>
  );
}

/* ─── Empty state ──────────────────────────────────────────────────────── */

function NotesPanelEmpty() {
  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center gap-2",
        "py-10 px-4 text-center"
      )}
      aria-live="polite"
    >
      <span
        aria-hidden="true"
        className={cn(
          "flex items-center justify-center w-10 h-10 rounded-full",
          "bg-secondary text-muted-foreground"
        )}
      >
        <BookOpen size={18} strokeWidth={1.5} />
      </span>
      <p className="text-sm font-medium text-foreground">No notes yet</p>
      <p className="text-xs text-muted-foreground leading-relaxed max-w-[16rem]">
        Select any verse text and choose &ldquo;Add Note&rdquo; to capture your thoughts.
      </p>
    </div>
  );
}

"use client";

/**
 * NoteEditor
 *
 * Inline modal / overlay for creating or editing a note.
 * Appears centred on all viewports.
 *
 * Pass `initialText` when editing an existing note.
 * `selectedText` is the quoted verse excerpt shown read-only above the textarea.
 *
 * Accessibility: traps focus within the dialog and closes on Escape.
 */

import { useEffect, useRef } from "react";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";

interface NoteEditorProps {
  verseRef: string;
  selectedText: string;
  initialText?: string;
  onSave: (text: string) => void;
  onClose: () => void;
}

export function NoteEditor({
  verseRef,
  selectedText,
  initialText = "",
  onSave,
  onClose,
}: NoteEditorProps) {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const dialogRef = useRef<HTMLDivElement>(null);

  /* Auto-focus textarea on mount */
  useEffect(() => {
    textareaRef.current?.focus();
  }, []);

  /* Close on Escape */
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, [onClose]);

  const handleSave = () => {
    const value = textareaRef.current?.value.trim() ?? "";
    if (value) onSave(value);
  };

  return (
    /* Backdrop */
    <div
      role="presentation"
      className="fixed inset-0 z-[60] flex items-center justify-center p-4"
      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
    >
      {/* Scrim */}
      <div
        aria-hidden="true"
        className="absolute inset-0 bg-foreground/20 backdrop-blur-[2px]"
      />

      {/* Dialog */}
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="note-editor-title"
        className={cn(
          "relative z-10 w-full max-w-md",
          "flex flex-col gap-4",
          "rounded-xl bg-card border border-border shadow-2xl",
          "p-5"
        )}
      >
        {/* Header */}
        <div className="flex items-start justify-between gap-3">
          <div>
            <h2
              id="note-editor-title"
              className="text-sm font-semibold font-sans text-foreground"
            >
              {initialText ? "Edit note" : "Add note"}
              <span className="ml-1.5 text-muted-foreground font-normal">
                — {verseRef}
              </span>
            </h2>
          </div>
          <button
            type="button"
            aria-label="Close note editor"
            onClick={onClose}
            className={cn(
              "p-1 rounded text-muted-foreground shrink-0",
              "hover:bg-secondary hover:text-foreground",
              "transition-colors duration-100 cursor-pointer",
              "focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
            )}
          >
            <X size={16} strokeWidth={2} aria-hidden="true" />
          </button>
        </div>

        {/* Selected text preview */}
        <blockquote
          className={cn(
            "border-l-[3px] border-verse-highlight-border pl-3",
            "text-xs italic text-muted-foreground leading-relaxed",
            "line-clamp-3 bg-verse-highlight/40 py-1.5 pr-2 rounded-r-sm"
          )}
        >
          &ldquo;{selectedText}&rdquo;
        </blockquote>

        {/* Textarea */}
        <textarea
          ref={textareaRef}
          defaultValue={initialText}
          placeholder="Write your note here…"
          rows={4}
          className={cn(
            "w-full resize-none rounded-md border border-input bg-background",
            "px-3 py-2 text-sm text-foreground placeholder:text-muted-foreground",
            "leading-relaxed font-sans",
            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60",
            "transition-shadow duration-150"
          )}
        />

        {/* Actions */}
        <div className="flex items-center justify-end gap-2">
          <button
            type="button"
            onClick={onClose}
            className={cn(
              "px-3 py-1.5 rounded-md text-sm font-medium",
              "bg-secondary text-secondary-foreground",
              "hover:bg-secondary/70 transition-colors duration-100 cursor-pointer",
              "focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
            )}
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={handleSave}
            className={cn(
              "px-3 py-1.5 rounded-md text-sm font-medium",
              "bg-primary text-primary-foreground",
              "hover:bg-primary/85 transition-colors duration-100 cursor-pointer",
              "focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
            )}
          >
            Save note
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

/**
 * useBibleSelection
 *
 * Tracks multi-verse text selection within a scrollable container and
 * computes the floating toolbar position.
 *
 * Returns:
 *  - selectedVerses: Set<number>  — verse numbers currently in the selection
 *  - selectedText:   string       — concatenated selected text
 *  - toolbarPos:     { top, left } | null  — document-relative position for <SelectionToolbar>
 *  - clearSelection: () => void
 *  - onMouseUp:      React mouse-up handler to attach to the reading container
 */

import { useState, useCallback } from "react";

export interface ToolbarPosition {
  top: number;
  left: number;
}

export interface BibleSelection {
  selectedVerses: Set<number>;
  selectedText: string;
  toolbarPos: ToolbarPosition | null;
  clearSelection: () => void;
  onContainerMouseUp: (e: React.MouseEvent<HTMLElement>) => void;
}

export function useBibleSelection(): BibleSelection {
  const [selectedVerses, setSelectedVerses] = useState<Set<number>>(new Set());
  const [selectedText, setSelectedText] = useState("");
  const [toolbarPos, setToolbarPos] = useState<ToolbarPosition | null>(null);

  const clearSelection = useCallback(() => {
    setSelectedVerses(new Set());
    setSelectedText("");
    setToolbarPos(null);
    window.getSelection()?.removeAllRanges();
  }, []);

  const onContainerMouseUp = useCallback((e: React.MouseEvent<HTMLElement>) => {
    // Small delay lets the browser finalise the selection range
    requestAnimationFrame(() => {
      const selection = window.getSelection();

      if (!selection || selection.isCollapsed || selection.rangeCount === 0) {
        return;
      }

      const text = selection.toString().trim();
      if (!text) return;

      /* ── Collect verse numbers within the selection ── */
      const range = selection.getRangeAt(0);
      const container = e.currentTarget;
      const verseEls = Array.from(
        container.querySelectorAll<HTMLElement>("[data-verse]")
      );

      const hitVerses = new Set<number>();
      verseEls.forEach((el) => {
        // Does this verse element overlap the selection range?
        const elRange = document.createRange();
        elRange.selectNodeContents(el);
        if (
          range.compareBoundaryPoints(Range.END_TO_START, elRange) < 0 &&
          range.compareBoundaryPoints(Range.START_TO_END, elRange) > 0
        ) {
          const verseNum = parseInt(el.dataset.verse ?? "0", 10);
          if (verseNum) hitVerses.add(verseNum);
        }
      });

      setSelectedVerses(hitVerses);
      setSelectedText(text);

      /* ── Position toolbar centred above the selection ── */
      const rect = range.getBoundingClientRect();
      setToolbarPos({
        top: rect.top + window.scrollY - 48, // 48px above = toolbar height + gap
        left: rect.left + rect.width / 2,
      });
    });
  }, []);

  return { selectedVerses, selectedText, toolbarPos, clearSelection, onContainerMouseUp };
}

"use client";

/**
 * /bible  — Bible Reader Page
 *
 * Layout (desktop):  [Header] [ReadingColumn | NotesPanel]
 * Layout (mobile):   [Header] [ReadingColumn] [NotesPanel (collapsed/expanded)]
 *
 * Component tree:
 *   BiblePage
 *   ├─ ReaderHeader       (book/chapter nav, notes-panel toggle on mobile)
 *   ├─ SelectionToolbar   (floats above selection)
 *   ├─ NoteEditor         (modal, appears on "Add Note")
 *   ├─ ReadingColumn
 *   │   └─ VerseBlock × N
 *   └─ NotesPanel
 *       └─ NoteCard × N
 */

import { useState, useCallback, useId } from "react";
import { BookOpen, ChevronLeft, ChevronRight, StickyNote } from "lucide-react";
import { cn } from "@/lib/utils";
import { VerseBlock } from "@/components/bible/verse-block";
import { SelectionToolbar } from "@/components/bible/selection-toolbar";
import { NotesPanel, type Note } from "@/components/bible/notes-panel";
import { NoteEditor } from "@/components/bible/note-editor";
import { useBibleSelection } from "@/hooks/use-bible-selection";

/* ─── Sample data ───────────────────────────────────────────────────────── */

const CHAPTER = { book: "John", chapter: 3 };

const VERSES = [
  { number: 1, text: "There was a man of the Pharisees named Nicodemus, a ruler of the Jews." },
  { number: 2, text: "This man came to Jesus by night and said to Him, \"Rabbi, we know that You are a teacher come from God; for no one can do these signs that You do unless God is with him.\"" },
  { number: 3, text: "Jesus answered and said to him, \"Most assuredly, I say to you, unless one is born again, he cannot see the kingdom of God.\"" },
  { number: 4, text: "Nicodemus said to Him, \"How can a man be born when he is old? Can he enter a second time into his mother's womb and be born?\"" },
  { number: 5, text: "Jesus answered, \"Most assuredly, I say to you, unless one is born of water and the Spirit, he cannot enter the kingdom of God.\"" },
  { number: 6, text: "That which is born of the flesh is flesh, and that which is born of the Spirit is spirit." },
  { number: 7, text: "Do not marvel that I said to you, 'You must be born again.'" },
  { number: 8, text: "The wind blows where it wishes, and you hear the sound of it, but cannot tell where it comes from and where it goes. So is everyone who is born of the Spirit." },
  { number: 9, text: "Nicodemus answered and said to Him, \"How can these things be?\"" },
  { number: 10, text: "Jesus answered and said to him, \"Are you the teacher of Israel, and do not know these things?\"" },
  { number: 11, text: "Most assuredly, I say to you, We speak what We know and testify what We have seen, and you do not receive Our witness." },
  { number: 12, text: "If I have told you earthly things and you do not believe, how will you believe if I tell you heavenly things?" },
  { number: 13, text: "No one has ascended to heaven but He who came down from heaven, that is, the Son of Man who is in heaven." },
  { number: 14, text: "And as Moses lifted up the serpent in the wilderness, even so must the Son of Man be lifted up," },
  { number: 15, text: "that whoever believes in Him should not perish but have eternal life." },
  { number: 16, text: "For God so loved the world that He gave His only begotten Son, that whoever believes in Him should not perish but have everlasting life." },
  { number: 17, text: "For God did not send His Son into the world to condemn the world, but that the world through Him might be saved." },
  { number: 18, text: "He who believes in Him is not condemned; but he who does not believe is condemned already, because he has not believed in the name of the only begotten Son of God." },
  { number: 19, text: "And this is the condemnation, that the light has come into the world, and men loved darkness rather than light, because their deeds were evil." },
  { number: 20, text: "For everyone practicing evil hates the light and does not come to the light, lest his deeds should be exposed." },
  { number: 21, text: "But he who does the truth comes to the light, that his deeds may be clearly seen, that they have been done in God." },
];

const INITIAL_NOTES: Note[] = [
  {
    id: "n1",
    verseRef: "v. 3",
    selectedText: "unless one is born again, he cannot see the kingdom of God.",
    noteText: "The Greek word 'anothen' means both 'again' and 'from above' — Nicodemus takes the earthly meaning, Jesus intends the heavenly.",
  },
  {
    id: "n2",
    verseRef: "v. 16",
    selectedText: "For God so loved the world that He gave His only begotten Son",
    noteText: "The hinge verse of the gospel. Scope: the whole world (kosmos). Cost: the only Son. Condition: belief. Result: not perish, but eternal life.",
  },
];

/* ─── Page ──────────────────────────────────────────────────────────────── */

export default function BiblePage() {
  /* Selection state */
  const { selectedVerses, selectedText, toolbarPos, clearSelection, onContainerMouseUp } =
    useBibleSelection();

  /* Highlight state — persisted set of verse numbers */
  const [highlighted, setHighlighted] = useState<Set<number>>(new Set([16]));

  /* Notes state */
  const [notes, setNotes] = useState<Note[]>(INITIAL_NOTES);
  const [notesPanelOpen, setNotesPanelOpen] = useState(true);

  /* Editor state */
  const [editorState, setEditorState] = useState<{
    open: boolean;
    editId?: string;
    verseRef: string;
    selectedText: string;
    initialText: string;
  }>({ open: false, verseRef: "", selectedText: "", initialText: "" });

  const uid = useId();

  /* ── Toolbar actions ─────────────────────────────────────────────── */

  const handleHighlight = useCallback(() => {
    setHighlighted((prev) => {
      const next = new Set(prev);
      selectedVerses.forEach((v) => next.add(v));
      return next;
    });
    clearSelection();
  }, [selectedVerses, clearSelection]);

  const handleAddNote = useCallback(() => {
    if (!selectedVerses.size) return;
    const sorted = Array.from(selectedVerses).sort((a, b) => a - b);
    const verseRef =
      sorted.length === 1
        ? `v. ${sorted[0]}`
        : `v. ${sorted[0]}–${sorted[sorted.length - 1]}`;
    setEditorState({
      open: true,
      verseRef,
      selectedText,
      initialText: "",
    });
  }, [selectedVerses, selectedText]);

  /* ── Note CRUD ───────────────────────────────────────────────────── */

  const handleSaveNote = useCallback(
    (text: string) => {
      if (editorState.editId) {
        setNotes((prev) =>
          prev.map((n) =>
            n.id === editorState.editId ? { ...n, noteText: text } : n
          )
        );
      } else {
        const newNote: Note = {
          id: `${uid}-${Date.now()}`,
          verseRef: editorState.verseRef,
          selectedText: editorState.selectedText,
          noteText: text,
        };
        setNotes((prev) => [...prev, newNote]);
        // Auto-highlight the verses when a note is added
        const vNums = parseVerseRef(editorState.verseRef);
        setHighlighted((prev) => {
          const next = new Set(prev);
          vNums.forEach((v) => next.add(v));
          return next;
        });
      }
      setEditorState((s) => ({ ...s, open: false, editId: undefined }));
      clearSelection();
    },
    [editorState, uid, clearSelection]
  );

  const handleEditNote = useCallback(
    (id: string) => {
      const note = notes.find((n) => n.id === id);
      if (!note) return;
      setEditorState({
        open: true,
        editId: id,
        verseRef: note.verseRef,
        selectedText: note.selectedText,
        initialText: note.noteText,
      });
    },
    [notes]
  );

  const handleDeleteNote = useCallback((id: string) => {
    setNotes((prev) => prev.filter((n) => n.id !== id));
  }, []);

  const chapterRef = `${CHAPTER.book} ${CHAPTER.chapter}`;

  return (
    <div className="flex flex-col min-h-dvh bg-background">
      {/* ── Top header ──────────────────────────────────────────────── */}
      <ReaderHeader
        chapterRef={chapterRef}
        noteCount={notes.length}
        notesPanelOpen={notesPanelOpen}
        onToggleNotes={() => setNotesPanelOpen((v) => !v)}
      />

      {/* ── Main content: reading + notes ───────────────────────────── */}
      <div className="flex flex-1 items-start relative">

        {/* Reading column */}
        <main
          className={cn(
            "flex-1 min-w-0 relative",
            "px-5 sm:px-8 md:px-12 lg:px-16 py-8",
            "max-w-3xl mx-auto w-full",
            /* On md+ when panel is open, pull left slightly */
            notesPanelOpen && "md:mx-0 md:ml-auto"
          )}
          onMouseUp={onContainerMouseUp}
        >
          {/* Chapter heading */}
          <header className="mb-8">
            <p className="text-xs font-sans font-semibold tracking-widest uppercase text-muted-foreground mb-1">
              {CHAPTER.book}
            </p>
            <h1 className="font-serif text-4xl font-bold text-foreground text-balance leading-tight">
              Chapter {CHAPTER.chapter}
            </h1>
            <div className="mt-3 h-px bg-border" aria-hidden="true" />
          </header>

          {/* Verse list */}
          <section aria-label={`${chapterRef} verses`} className="flex flex-col gap-0.5">
            {VERSES.map((v) => (
              <VerseBlock
                key={v.number}
                number={v.number}
                text={v.text}
                highlighted={highlighted.has(v.number)}
                selected={selectedVerses.has(v.number)}
                hasNote={notes.some((n) => parseVerseRef(n.verseRef).includes(v.number))}
              />
            ))}
          </section>

          {/* Chapter nav */}
          <div className="mt-10 flex items-center justify-between">
            <NavButton icon={<ChevronLeft size={16} />} label="Previous chapter" />
            <NavButton icon={<ChevronRight size={16} />} label="Next chapter" flip />
          </div>
        </main>

        {/* Notes panel — right sidebar on md+, stacked below on mobile */}
        <NotesPanel
          chapterRef={chapterRef}
          notes={notes}
          open={notesPanelOpen}
          onAddNote={() =>
            setEditorState({
              open: true,
              verseRef: "",
              selectedText: "",
              initialText: "",
            })
          }
          onEditNote={handleEditNote}
          onDeleteNote={handleDeleteNote}
          className="md:sticky md:top-[3.5rem]"
        />
      </div>

      {/* ── Floating selection toolbar ───────────────────────────────── */}
      {toolbarPos && (
        <SelectionToolbar
          position={toolbarPos}
          onHighlight={handleHighlight}
          onAddNote={handleAddNote}
          onCancel={clearSelection}
        />
      )}

      {/* ── Note editor modal ────────────────────────────────────────── */}
      {editorState.open && (
        <NoteEditor
          verseRef={editorState.verseRef || "General"}
          selectedText={editorState.selectedText || "No text selected"}
          initialText={editorState.initialText}
          onSave={handleSaveNote}
          onClose={() =>
            setEditorState((s) => ({ ...s, open: false, editId: undefined }))
          }
        />
      )}
    </div>
  );
}

/* ─── Sub-components ────────────────────────────────────────────────────── */

interface ReaderHeaderProps {
  chapterRef: string;
  noteCount: number;
  notesPanelOpen: boolean;
  onToggleNotes: () => void;
}

function ReaderHeader({
  chapterRef,
  noteCount,
  notesPanelOpen,
  onToggleNotes,
}: ReaderHeaderProps) {
  return (
    <header
      className={cn(
        "sticky top-0 z-30 shrink-0",
        "flex items-center justify-between gap-4",
        "px-5 sm:px-8 h-14",
        "bg-background/95 backdrop-blur-sm border-b border-border"
      )}
    >
      {/* Brand / breadcrumb */}
      <div className="flex items-center gap-2 min-w-0">
        <BookOpen size={18} strokeWidth={1.5} className="text-primary shrink-0" aria-hidden="true" />
        <span className="font-sans text-sm font-semibold text-foreground truncate">
          {chapterRef}
        </span>
      </div>

      {/* Right actions */}
      <div className="flex items-center gap-2">
        {/* Translation badge */}
        <span
          className={cn(
            "hidden sm:inline-flex items-center px-2 py-0.5 rounded",
            "text-[0.65rem] font-sans font-semibold tracking-wide uppercase",
            "bg-secondary text-secondary-foreground"
          )}
        >
          NKJV
        </span>

        {/* Notes toggle */}
        <button
          type="button"
          aria-label={notesPanelOpen ? "Hide notes panel" : "Show notes panel"}
          aria-pressed={notesPanelOpen}
          onClick={onToggleNotes}
          className={cn(
            "relative flex items-center gap-1.5 px-2.5 py-1.5 rounded-md",
            "text-xs font-medium font-sans",
            "transition-colors duration-100 cursor-pointer",
            "focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
            notesPanelOpen
              ? "bg-primary text-primary-foreground"
              : "bg-secondary text-secondary-foreground hover:bg-secondary/70"
          )}
        >
          <StickyNote size={13} strokeWidth={2} aria-hidden="true" />
          <span className="hidden sm:inline">Notes</span>
          {noteCount > 0 && (
            <span
              aria-label={`${noteCount} notes`}
              className={cn(
                "flex items-center justify-center",
                "w-4 h-4 rounded-full text-[0.6rem] font-bold tabular-nums leading-none",
                notesPanelOpen
                  ? "bg-primary-foreground/20 text-primary-foreground"
                  : "bg-primary text-primary-foreground"
              )}
            >
              {noteCount}
            </span>
          )}
        </button>
      </div>
    </header>
  );
}

interface NavButtonProps {
  icon: React.ReactNode;
  label: string;
  flip?: boolean;
}

function NavButton({ icon, label, flip = false }: NavButtonProps) {
  return (
    <button
      type="button"
      aria-label={label}
      className={cn(
        "flex items-center gap-1.5 px-3 py-2 rounded-md",
        "text-sm font-medium font-sans text-muted-foreground",
        "border border-border bg-card",
        "hover:bg-secondary hover:text-foreground",
        "transition-colors duration-150 cursor-pointer",
        "focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
      )}
    >
      {!flip && icon}
      <span>{label}</span>
      {flip && icon}
    </button>
  );
}

/* ─── Utility ───────────────────────────────────────────────────────────── */

/** Parse "v. 3" or "v. 3–5" into an array of verse numbers */
function parseVerseRef(ref: string): number[] {
  const match = ref.match(/(\d+)(?:[–\-](\d+))?/);
  if (!match) return [];
  const start = parseInt(match[1], 10);
  const end = match[2] ? parseInt(match[2], 10) : start;
  return Array.from({ length: end - start + 1 }, (_, i) => start + i);
}

import { redirect } from "next/navigation";

export default function RootPage() {
  redirect("/bible");
}

