/**
 * SelectionToolbar
 *
 * A compact floating toolbar that appears near a text selection.
 * Position it with `style={{ top, left }}` from a parent that
 * reads `window.getSelection()` coordinates.
 *
 * Integration hint:
 *   const rect = selection.getRangeAt(0).getBoundingClientRect();
 *   setToolbar({ top: rect.top + scrollY - 48, left: rect.left + rect.width / 2 });
 */

import { Highlighter, StickyNote, X } from "lucide-react";
import { cn } from "@/lib/utils";

interface SelectionToolbarProps {
  /** Absolute pixel position relative to the scroll container / document */
  position: { top: number; left: number };
  onHighlight: () => void;
  onAddNote: () => void;
  onCancel: () => void;
  className?: string;
}

export function SelectionToolbar({
  position,
  onHighlight,
  onAddNote,
  onCancel,
  className,
}: SelectionToolbarProps) {
  return (
    /**
     * Outer wrapper: absolutely positioned, centred on the midpoint of the
     * selection via `translate-x-[-50%]`.  `z-50` keeps it above verse text.
     *
     * Tailwind classes to copy if you inline this instead:
     *   "absolute z-50 -translate-x-1/2 flex items-center gap-px
     *    rounded-lg shadow-lg overflow-hidden border border-toolbar-bg/20
     *    bg-[var(--toolbar-bg)] text-[var(--toolbar-fg)]"
     */
    <div
      role="toolbar"
      aria-label="Selection actions"
      className={cn(
        "absolute z-50 -translate-x-1/2",
        "flex items-center gap-px rounded-lg overflow-hidden",
        "shadow-[0_4px_20px_rgba(0,0,0,0.35)]",
        "bg-toolbar-bg text-toolbar-fg",
        "border border-white/10",
        className
      )}
      style={{ top: position.top, left: position.left }}
    >
      {/* Pointer / caret pointing downward — pure CSS triangle */}
      <span
        aria-hidden="true"
        className={cn(
          "absolute -bottom-[6px] left-1/2 -translate-x-1/2",
          "w-0 h-0",
          "border-l-[6px] border-l-transparent",
          "border-r-[6px] border-r-transparent",
          "border-t-[6px] border-t-toolbar-bg"
        )}
      />

      <ToolbarButton
        icon={<Highlighter size={14} strokeWidth={2} />}
        label="Highlight selection"
        onClick={onHighlight}
        colorClass="hover:bg-amber-600"
      />

      <div className="w-px h-5 bg-white/15 shrink-0" aria-hidden="true" />

      <ToolbarButton
        icon={<StickyNote size={14} strokeWidth={2} />}
        label="Add note to selection"
        onClick={onAddNote}
        colorClass="hover:bg-primary/80"
      />

      <div className="w-px h-5 bg-white/15 shrink-0" aria-hidden="true" />

      <ToolbarButton
        icon={<X size={14} strokeWidth={2.5} />}
        label="Cancel selection"
        onClick={onCancel}
        colorClass="hover:bg-white/10"
      />
    </div>
  );
}

