/**
 * VerseBlock
 *
 * Renders a single Bible verse with:
 *  - verse number superscript
 *  - optional highlight state (amber wash)
 *  - optional note indicator dot
 *  - selected state (blue-ish ring, used during multi-verse drag)
 *
 * Usage:
 *   <VerseBlock
 *     number={3}
 *     text="For God so loved the world..."
 *     highlighted
 *     hasNote
 *     onMouseUp={handleMouseUp}
 *   />
 *
 * Tailwind class summary for quick reference:
 *   Highlighted:  bg-verse-highlight border-l-2 border-verse-highlight-border
 *   Selected:     ring-1 ring-primary/40 bg-primary/5
 *   Note dot:     w-1.5 h-1.5 rounded-full bg-note-stripe
 */

import { cn } from "@/lib/utils";

export interface VerseBlockProps {
  number: number;
  text: string;
  highlighted?: boolean;
  selected?: boolean;
  hasNote?: boolean;
  "data-verse"?: number;
  onMouseUp?: (e: React.MouseEvent<HTMLParagraphElement>) => void;
  onMouseDown?: (e: React.MouseEvent<HTMLParagraphElement>) => void;
  className?: string;
}

export function VerseBlock({
  number,
  text,
  highlighted = false,
  selected = false,
  hasNote = false,
  onMouseUp,
  onMouseDown,
  className,
  ...rest
}: VerseBlockProps) {
  return (
    <p
      data-verse={number}
      onMouseUp={onMouseUp}
      onMouseDown={onMouseDown}
      className={cn(
        /* Base */
        "relative group pl-6 pr-2 py-1.5 rounded-sm",
        "font-serif text-base leading-relaxed text-foreground",
        "transition-colors duration-150 cursor-text select-text",
        /* Highlighted state */
        highlighted && [
          "bg-verse-highlight",
          "border-l-[3px] border-verse-highlight-border",
          "pl-5", // compensate for border
        ],
        /* Selected (active drag) state */
        selected && !highlighted && [
          "bg-primary/8 ring-1 ring-inset ring-primary/30",
        ],
        className
      )}
      {...rest}
    >
      {/* Verse number */}
      <sup
        className={cn(
          "mr-1.5 text-[0.65rem] font-semibold select-none",
          "font-sans tabular-nums",
          highlighted ? "text-note-stripe" : "text-muted-foreground"
        )}
        aria-label={`Verse ${number}`}
      >
        {number}
      </sup>

      {text}

      {/* Note indicator dot */}
      {hasNote && (
        <span
          aria-label="Has note"
          title="Note attached"
          className={cn(
            "inline-block ml-1.5 mb-0.5 align-middle",
            "w-1.5 h-1.5 rounded-full shrink-0",
            "bg-note-stripe opacity-80"
          )}
        />
      )}
    </p>
  );
}

