"use client";

/**
 * NoteEditor
 *
 * Inline modal / overlay for creating or editing a note.
 * Appears centred on all viewports.
 *
 * Pass `initialText` when editing an existing note.
 * `selectedText` is the quoted verse excerpt shown read-only above the textarea.
 *
 * Accessibility: traps focus within the dialog and closes on Escape.
 */

import { useEffect, useRef } from "react";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";

interface NoteEditorProps {
  verseRef: string;
  selectedText: string;
  initialText?: string;
  onSave: (text: string) => void;
  onClose: () => void;
}

export function NoteEditor({
  verseRef,
  selectedText,
  initialText = "",
  onSave,
  onClose,
}: NoteEditorProps) {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const dialogRef = useRef<HTMLDivElement>(null);

  /* Auto-focus textarea on mount */
  useEffect(() => {
    textareaRef.current?.focus();
  }, []);

  /* Close on Escape */
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, [onClose]);

  const handleSave = () => {
    const value = textareaRef.current?.value.trim() ?? "";
    if (value) onSave(value);
  };

  return (
    /* Backdrop */
    <div
      role="presentation"
      className="fixed inset-0 z-[60] flex items-center justify-center p-4"
      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
    >
      {/* Scrim */}
      <div
        aria-hidden="true"
        className="absolute inset-0 bg-foreground/20 backdrop-blur-[2px]"
      />

      {/* Dialog */}
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="note-editor-title"
        className={cn(
          "relative z-10 w-full max-w-md",
          "flex flex-col gap-4",
          "rounded-xl bg-card border border-border shadow-2xl",
          "p-5"
        )}
      >
        {/* Header */}
        <div className="flex items-start justify-between gap-3">
          <div>
            <h2
              id="note-editor-title"
              className="text-sm font-semibold font-sans text-foreground"
            >
              {initialText ? "Edit note" : "Add note"}
              <span className="ml-1.5 text-muted-foreground font-normal">
                — {verseRef}
              </span>
            </h2>
          </div>
          <button
            type="button"
            aria-label="Close note editor"
            onClick={onClose}
            className={cn(
              "p-1 rounded text-muted-foreground shrink-0",
              "hover:bg-secondary hover:text-foreground",
              "transition-colors duration-100 cursor-pointer",
              "focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
            )}
          >
            <X size={16} strokeWidth={2} aria-hidden="true" />
          </button>
        </div>

        {/* Selected text preview */}
        <blockquote
          className={cn(
            "border-l-[3px] border-verse-highlight-border pl-3",
            "text-xs italic text-muted-foreground leading-relaxed",
            "line-clamp-3 bg-verse-highlight/40 py-1.5 pr-2 rounded-r-sm"
          )}
        >
          &ldquo;{selectedText}&rdquo;
        </blockquote>

        {/* Textarea */}
        <textarea
          ref={textareaRef}
          defaultValue={initialText}
          placeholder="Write your note here…"
          rows={4}
          className={cn(
            "w-full resize-none rounded-md border border-input bg-background",
            "px-3 py-2 text-sm text-foreground placeholder:text-muted-foreground",
            "leading-relaxed font-sans",
            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60",
            "transition-shadow duration-150"
          )}
        />

        {/* Actions */}
        <div className="flex items-center justify-end gap-2">
          <button
            type="button"
            onClick={onClose}
            className={cn(
              "px-3 py-1.5 rounded-md text-sm font-medium",
              "bg-secondary text-secondary-foreground",
              "hover:bg-secondary/70 transition-colors duration-100 cursor-pointer",
              "focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
            )}
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={handleSave}
            className={cn(
              "px-3 py-1.5 rounded-md text-sm font-medium",
              "bg-primary text-primary-foreground",
              "hover:bg-primary/85 transition-colors duration-100 cursor-pointer",
              "focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
            )}
          >
            Save note
          </button>
        </div>
      </div>
    </div>
  );
}

