/**
 * useBibleSelection
 *
 * Tracks multi-verse text selection within a scrollable container and
 * computes the floating toolbar position.
 *
 * Returns:
 *  - selectedVerses: Set<number>  — verse numbers currently in the selection
 *  - selectedText:   string       — concatenated selected text
 *  - toolbarPos:     { top, left } | null  — document-relative position for <SelectionToolbar>
 *  - clearSelection: () => void
 *  - onMouseUp:      React mouse-up handler to attach to the reading container
 */

import { useState, useCallback } from "react";

export interface ToolbarPosition {
  top: number;
  left: number;
}

export interface BibleSelection {
  selectedVerses: Set<number>;
  selectedText: string;
  toolbarPos: ToolbarPosition | null;
  clearSelection: () => void;
  onContainerMouseUp: (e: React.MouseEvent<HTMLElement>) => void;
}

export function useBibleSelection(): BibleSelection {
  const [selectedVerses, setSelectedVerses] = useState<Set<number>>(new Set());
  const [selectedText, setSelectedText] = useState("");
  const [toolbarPos, setToolbarPos] = useState<ToolbarPosition | null>(null);

  const clearSelection = useCallback(() => {
    setSelectedVerses(new Set());
    setSelectedText("");
    setToolbarPos(null);
    window.getSelection()?.removeAllRanges();
  }, []);

  const onContainerMouseUp = useCallback((e: React.MouseEvent<HTMLElement>) => {
    // Small delay lets the browser finalise the selection range
    requestAnimationFrame(() => {
      const selection = window.getSelection();

      if (!selection || selection.isCollapsed || selection.rangeCount === 0) {
        return;
      }

      const text = selection.toString().trim();
      if (!text) return;

      /* ── Collect verse numbers within the selection ── */
      const range = selection.getRangeAt(0);
      const container = e.currentTarget;
      const verseEls = Array.from(
        container.querySelectorAll<HTMLElement>("[data-verse]")
      );

      const hitVerses = new Set<number>();
      verseEls.forEach((el) => {
        // Does this verse element overlap the selection range?
        const elRange = document.createRange();
        elRange.selectNodeContents(el);
        if (
          range.compareBoundaryPoints(Range.END_TO_START, elRange) < 0 &&
          range.compareBoundaryPoints(Range.START_TO_END, elRange) > 0
        ) {
          const verseNum = parseInt(el.dataset.verse ?? "0", 10);
          if (verseNum) hitVerses.add(verseNum);
        }
      });

      setSelectedVerses(hitVerses);
      setSelectedText(text);

      /* ── Position toolbar centred above the selection ── */
      const rect = range.getBoundingClientRect();
      setToolbarPos({
        top: rect.top + window.scrollY - 48, // 48px above = toolbar height + gap
        left: rect.left + rect.width / 2,
      });
    });
  }, []);

  return { selectedVerses, selectedText, toolbarPos, clearSelection, onContainerMouseUp };
}

