  { number: 19, text: "And this is the condemnation, that the light has come into the world, and men loved darkness rather than light, because their deeds were evil." },
  { number: 20, text: "For everyone practicing evil hates the light and does not come to the light, lest his deeds should be exposed." },
  { number: 21, text: "But he who does the truth comes to the light, that his deeds may be clearly seen, that they have been done in God." },
];

const INITIAL_NOTES: Note[] = [
  {
    id: "n1",
    verseRef: "v. 3",
    selectedText: "unless one is born again, he cannot see the kingdom of God.",
    noteText: "The Greek word 'anothen' means both 'again' and 'from above' — Nicodemus takes the earthly meaning, Jesus intends the heavenly.",
  },
  {
