  },
];

/* ─── Page ──────────────────────────────────────────────────────────────── */

export default function BiblePage() {
  /* Selection state */
  const { selectedVerses, selectedText, toolbarPos, clearSelection, onContainerMouseUp } =
    useBibleSelection();

  /* Highlight state — persisted set of verse numbers */
  const [highlighted, setHighlighted] = useState<Set<number>>(new Set([16]));

  /* Notes state */
  const [notes, setNotes] = useState<Note[]>(INITIAL_NOTES);
  const [notesPanelOpen, setNotesPanelOpen] = useState(true);

  /* Editor state */
  const [editorState, setEditorState] = useState<{
    open: boolean;
    editId?: string;
    verseRef: string;
    selectedText: string;
    initialText: string;
  }>({ open: false, verseRef: "", selectedText: "", initialText: "" });

  const uid = useId();

  /* ── Toolbar actions ─────────────────────────────────────────────── */

  const handleHighlight = useCallback(() => {
    setHighlighted((prev) => {
      const next = new Set(prev);
      selectedVerses.forEach((v) => next.add(v));
      return next;
    });
    clearSelection();
  }, [selectedVerses, clearSelection]);

  const handleAddNote = useCallback(() => {
    if (!selectedVerses.size) return;
    const sorted = Array.from(selectedVerses).sort((a, b) => a - b);
    const verseRef =
      sorted.length === 1
        ? `v. ${sorted[0]}`
        : `v. ${sorted[0]}–${sorted[sorted.length - 1]}`;
    setEditorState({
      open: true,
      verseRef,
      selectedText,
      initialText: "",
    });
  }, [selectedVerses, selectedText]);

  /* ── Note CRUD ───────────────────────────────────────────────────── */

  const handleSaveNote = useCallback(
    (text: string) => {
      if (editorState.editId) {
        setNotes((prev) =>
          prev.map((n) =>
            n.id === editorState.editId ? { ...n, noteText: text } : n
          )
        );
      } else {
        const newNote: Note = {
          id: `${uid}-${Date.now()}`,
          verseRef: editorState.verseRef,
          selectedText: editorState.selectedText,
          noteText: text,
        };
        setNotes((prev) => [...prev, newNote]);
        // Auto-highlight the verses when a note is added
        const vNums = parseVerseRef(editorState.verseRef);
        setHighlighted((prev) => {
          const next = new Set(prev);
          vNums.forEach((v) => next.add(v));
          return next;
        });
      }
      setEditorState((s) => ({ ...s, open: false, editId: undefined }));
      clearSelection();
    },
    [editorState, uid, clearSelection]
  );

  const handleEditNote = useCallback(
    (id: string) => {
      const note = notes.find((n) => n.id === id);
      if (!note) return;
      setEditorState({
        open: true,
        editId: id,
        verseRef: note.verseRef,
        selectedText: note.selectedText,
        initialText: note.noteText,
      });
    },
    [notes]
  );

  const handleDeleteNote = useCallback((id: string) => {
    setNotes((prev) => prev.filter((n) => n.id !== id));
  }, []);

  const chapterRef = `${CHAPTER.book} ${CHAPTER.chapter}`;

  return (
    <div className="flex flex-col min-h-dvh bg-background">
      {/* ── Top header ──────────────────────────────────────────────── */}
      <ReaderHeader
        chapterRef={chapterRef}
        noteCount={notes.length}
        notesPanelOpen={notesPanelOpen}
        onToggleNotes={() => setNotesPanelOpen((v) => !v)}
      />

      {/* ── Main content: reading + notes ───────────────────────────── */}
      <div className="flex flex-1 items-start relative">

        {/* Reading column */}
        <main
          className={cn(
            "flex-1 min-w-0 relative",
            "px-5 sm:px-8 md:px-12 lg:px-16 py-8",
            "max-w-3xl mx-auto w-full",
            /* On md+ when panel is open, pull left slightly */
            notesPanelOpen && "md:mx-0 md:ml-auto"
          )}
          onMouseUp={onContainerMouseUp}
        >
          {/* Chapter heading */}
          <header className="mb-8">
            <p className="text-xs font-sans font-semibold tracking-widest uppercase text-muted-foreground mb-1">
              {CHAPTER.book}
            </p>
            <h1 className="font-serif text-4xl font-bold text-foreground text-balance leading-tight">
              Chapter {CHAPTER.chapter}
            </h1>
            <div className="mt-3 h-px bg-border" aria-hidden="true" />
          </header>

          {/* Verse list */}
          <section aria-label={`${chapterRef} verses`} className="flex flex-col gap-0.5">
            {VERSES.map((v) => (
              <VerseBlock
                key={v.number}
                number={v.number}
                text={v.text}
                highlighted={highlighted.has(v.number)}
                selected={selectedVerses.has(v.number)}
                hasNote={notes.some((n) => parseVerseRef(n.verseRef).includes(v.number))}
              />
            ))}
          </section>

          {/* Chapter nav */}
          <div className="mt-10 flex items-center justify-between">
            <NavButton icon={<ChevronLeft size={16} />} label="Previous chapter" />
            <NavButton icon={<ChevronRight size={16} />} label="Next chapter" flip />
          </div>
        </main>

        {/* Notes panel — right sidebar on md+, stacked below on mobile */}
        <NotesPanel
          chapterRef={chapterRef}
          notes={notes}
          open={notesPanelOpen}
          onAddNote={() =>
            setEditorState({
              open: true,
              verseRef: "",
              selectedText: "",
              initialText: "",
            })
          }
          onEditNote={handleEditNote}
          onDeleteNote={handleDeleteNote}
          className="md:sticky md:top-[3.5rem]"
        />
      </div>

      {/* ── Floating selection toolbar ───────────────────────────────── */}
      {toolbarPos && (
        <SelectionToolbar
          position={toolbarPos}
          onHighlight={handleHighlight}
          onAddNote={handleAddNote}
          onCancel={clearSelection}
        />
      )}

      {/* ── Note editor modal ────────────────────────────────────────── */}
      {editorState.open && (
        <NoteEditor
          verseRef={editorState.verseRef || "General"}
          selectedText={editorState.selectedText || "No text selected"}
          initialText={editorState.initialText}
          onSave={handleSaveNote}
          onClose={() =>
            setEditorState((s) => ({ ...s, open: false, editId: undefined }))
          }
        />
      )}
    </div>
  );
}

